CREATE INDEX user_moderation_actions_target_created_idx ON public.user_moderation_actions USING btree (target_user_id, created_at DESC);
CREATE INDEX verified_facts_subject_business_idx ON public.verified_facts USING btree (subject_business_id);
CREATE INDEX verified_facts_subject_user_idx ON public.verified_facts USING btree (subject_user_id);
CREATE INDEX verified_facts_verified_by_idx ON public.verified_facts USING btree (verified_by);
create view "public"."user_roles" with (security_invoker=true) as  SELECT id AS user_id,
    role::text AS role
   FROM profiles p
  WHERE id = auth.uid() OR is_admin();
alter view "public"."user_roles" owner to "postgres";
